"""Maximum XOR of Two Numbers in an Array — build the answer bit by bit.

At each bit, assume the answer can have a 1 there and check whether some prefix
pair actually produces it; a^b == target means a == target^b.

Time: O(32n)   Space: O(n)
"""
from typing import List


class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        best = 0
        for bit in range(31, -1, -1):
            best <<= 1
            prefixes = {value >> bit for value in nums}
            candidate = best | 1
            if any(candidate ^ prefix in prefixes for prefix in prefixes):
                best = candidate
        return best
